        INSERT INTO public.topics (title, slug, usmle_step, "order")
    INSERT INTO public.mcqs (topic_id, question, options, correct_index, explanation, "order") VALUES
    (v_topic_id, 'A 7-year-old unvaccinated child presents with fever, sore throat, and a gray pseudomembrane over the pharynx. Cervical lymphadenopathy and neck swelling are present. Which of the following best explains the pathogenic mechanism of this organism?', '["Inactivation of 60S ribosomal subunit", "ADP-ribosylation of elongation factor-2", "Activation of adenylate cyclase by Gs stimulation", "Cleavage of SNARE proteins in inhibitory neurons", "Inhibition of peptidoglycan cross-linking"]', 1, 'This is Corynebacterium diphtheriae. Diphtheria toxin ADP-ribosylates EF-2, halting protein synthesis. The membrane should not be forcefully removed because of bleeding risk.', 1),
    (v_topic_id, 'A college student living in a dormitory develops meningitis with fever, headache, photophobia, and petechial rash. The causative organism is best described as:', '["Gram-positive lancet-shaped diplococcus", "Acid-fast branching rod", "Oxidase-positive gram-negative diplococcus", "Catalase-negative gram-positive cocci in chains", "Encapsulated gram-negative coccobacillus requiring X and V factors"]', 2, 'Neisseria meningitidis causes meningitis in crowded settings and can cause meningococcemia with petechiae. It is an oxidase-positive gram-negative diplococcus.', 2),
    (v_topic_id, 'A 63-year-old alcoholic man develops lobar pneumonia with rusty sputum. Which virulence factor most strongly contributes to the organism’s ability to evade phagocytosis?', '["M protein", "Capsule", "IgA protease", "Exotoxin A", "Lipid A"]', 1, 'Streptococcus pneumoniae is the classic cause of lobar pneumonia with rusty sputum. Its polysaccharide capsule is its major virulence factor.', 3),
    (v_topic_id, 'A patient with recurrent otitis media and sinusitis is infected repeatedly with encapsulated organisms. Deficiency of which splenic function most likely predisposes to severe infection with Streptococcus pneumoniae?', '["Production of IgE", "Clearance of opsonized bacteria", "T-cell maturation", "Eosinophil activation", "Complement synthesis"]', 1, 'The spleen is critical for clearing opsonized encapsulated organisms. Patients with asplenia are at high risk for pneumococcal sepsis.', 4),
    (v_topic_id, 'A newborn develops meningitis after maternal exposure during pregnancy. The organism is a gram-positive rod showing tumbling motility and intracellular spread via actin polymerization. Which organism is most likely?', '["Bacillus anthracis", "Corynebacterium diphtheriae", "Listeria monocytogenes", "Actinomyces israelii", "Nocardia asteroides"]', 2, 'Listeria causes neonatal sepsis/meningitis, especially from contaminated dairy or deli meats in pregnancy. It shows tumbling motility and intracellular spread using actin rockets.', 5),
    (v_topic_id, 'A man develops descending paralysis after eating home-canned vegetables. Which of the following is the mechanism of the responsible toxin?', '["Blocks release of glycine and GABA", "Inhibits release of acetylcholine at presynaptic terminals", "Inhibits 60S ribosomal subunit", "Activates adenylate cyclase through Gi inhibition", "Causes demyelination of peripheral nerves"]', 1, 'Clostridium botulinum toxin prevents acetylcholine release, causing descending flaccid paralysis.', 6),
    (v_topic_id, 'A child steps on a rusty nail and later develops trismus and generalized spasticity. The toxin produced by the causative organism acts by:', '["Blocking acetylcholine release", "Blocking GABA and glycine release", "Increasing cAMP via Gs activation", "Inhibiting EF-2", "Activating guanylate cyclase"]', 1, 'Clostridium tetani toxin cleaves synaptobrevin in inhibitory interneurons, blocking GABA and glycine release, causing spastic paralysis.', 7),
    (v_topic_id, 'A hospitalized patient develops watery diarrhea after clindamycin therapy. Colonoscopy shows yellow-white plaques. The causative organism primarily produces toxins that:', '["ADP-ribosylate EF-2", "Inhibit 60S ribosome function", "Disrupt the actin cytoskeleton", "Activate Gs protein", "Cause pore formation in RBC membranes"]', 2, 'Clostridioides difficile toxins A and B inactivate Rho GTPases and disrupt the cytoskeleton, causing pseudomembranous colitis.', 8),
    (v_topic_id, 'A traumatic wound becomes swollen, painful, and crepitant. Imaging reveals gas in soft tissue. Which enzyme/toxin is most directly responsible for the severe myonecrosis?', '["Lecithinase", "Urease", "Coagulase", "Hyaluronidase only", "DNase"]', 0, 'Clostridium perfringens alpha toxin is a lecithinase (phospholipase C) that destroys cell membranes and causes gas gangrene.', 9),
    (v_topic_id, 'An elderly patient with poor dentition aspirates oral contents and develops foul-smelling lung abscesses. The likely pathogens are best described as:', '["Aerobic gram-positive cocci", "Anaerobic oral flora", "Acid-fast rods", "Spore-forming aerobes", "Encapsulated intracellular bacteria"]', 1, 'Aspiration pneumonia with lung abscesses is classically caused by anaerobic oral flora such as Bacteroides, Fusobacterium, Peptostreptococcus.', 10),
    (v_topic_id, 'A ranch worker develops a painless black eschar on the hand after exposure to animal hides. The capsule of the causative organism is composed of:', '["Polysaccharide", "Hyaluronic acid", "Poly-D-glutamate", "Mycolic acid", "Dextran"]', 2, 'Bacillus anthracis has a unique poly-D-glutamate capsule, unlike the polysaccharide capsules of most bacteria.', 11),
    (v_topic_id, 'A patient has pneumonia with “currant jelly” sputum. The organism is a lactose-fermenting, heavily encapsulated gram-negative rod. Which is the most likely organism?', '["Pseudomonas aeruginosa", "Klebsiella pneumoniae", "Legionella pneumophila", "Serratia marcescens", "Proteus mirabilis"]', 1, 'Klebsiella causes severe pneumonia in alcoholics and debilitated patients. It is a lactose-fermenting encapsulated gram-negative rod.', 12),
    (v_topic_id, 'A catheterized patient develops a urinary tract infection. The urine is alkaline, and there are struvite stones. Which bacterial property explains these findings?', '["Oxidase positivity", "Coagulase production", "Urease production", "Hemolysin release", "Capsule synthesis"]', 2, 'Proteus mirabilis is urease positive. Urease alkalinizes urine, promoting struvite stones.', 13),
    (v_topic_id, 'A sexually active young woman develops cystitis caused by a novobiocin-resistant gram-positive coccus. Which organism is most likely?', '["Staphylococcus epidermidis", "Staphylococcus saprophyticus", "Enterococcus faecalis", "Streptococcus agalactiae", "Micrococcus luteus"]', 1, 'S. saprophyticus causes UTIs in sexually active young women and is novobiocin resistant.', 14),
    (v_topic_id, 'A patient develops infective endocarditis on a prosthetic valve. The organism is a coagulase-negative, novobiocin-sensitive gram-positive coccus that forms biofilms. Which organism is most likely?', '["Staphylococcus aureus", "Staphylococcus saprophyticus", "Staphylococcus epidermidis", "Streptococcus mutans", "Enterococcus faecium"]', 2, 'S. epidermidis commonly infects prosthetic devices through biofilm formation.', 15),
    (v_topic_id, 'A man who injects drugs intravenously develops acute infective endocarditis. Blood culture reveals catalase-positive, coagulase-positive gram-positive cocci in clusters. Which organism is most likely?', '["Staphylococcus aureus", "Staphylococcus epidermidis", "Streptococcus gallolyticus", "Enterococcus faecalis", "Streptococcus viridans"]', 0, 'S. aureus causes acute, aggressive endocarditis, especially in IV drug users.', 16),
    (v_topic_id, 'A child has honey-colored crusted skin lesions around the mouth. Which organism is a classic cause?', '["Staphylococcus aureus", "Mycobacterium tuberculosis", "Clostridium tetani", "Corynebacterium diphtheriae", "Neisseria meningitidis"]', 0, 'Impetigo is classically caused by S. aureus or Streptococcus pyogenes.', 17),
    (v_topic_id, 'A patient develops fever and diffuse sunburn-like rash with hypotension after prolonged tampon use. The syndrome is due to:', '["Endotoxin-mediated cytokine release", "Preformed enterotoxin ingestion", "Superantigen-mediated T-cell activation", "Immune complex deposition", "Delayed-type hypersensitivity"]', 2, 'TSST-1 from S. aureus is a superantigen causing toxic shock syndrome.', 18),
    (v_topic_id, 'A child has sore throat and fever. Untreated infection is followed weeks later by migratory arthritis and carditis. Which virulence factor is most associated with the original organism?', '["Polysaccharide capsule identical to host tissue", "M protein", "Coagulase", "Lipooligosaccharide", "Mycolic acid"]', 1, 'Streptococcus pyogenes causes pharyngitis and rheumatic fever. M protein is its major virulence factor.', 19),
    (v_topic_id, 'A patient presents with cellulitis and rapidly spreading erythema. Culture shows beta-hemolytic, bacitracin-sensitive gram-positive cocci in chains. Which organism is most likely?', '["Streptococcus agalactiae", "Enterococcus faecalis", "Streptococcus pyogenes", "Staphylococcus aureus", "Viridans streptococci"]', 2, 'Group A strep is beta-hemolytic, bacitracin sensitive, and causes cellulitis, pharyngitis, impetigo, nec fasc.', 20),
    (v_topic_id, 'A neonate develops pneumonia, sepsis, and meningitis after vaginal delivery. The likely organism is best identified by which feature?', '["Bacitracin sensitivity", "CAMP positivity", "Optochin sensitivity", "Coagulase positivity", "Urease positivity"]', 1, 'Streptococcus agalactiae (Group B strep) is CAMP positive and causes neonatal sepsis and meningitis.', 21),
    (v_topic_id, 'A patient develops subacute bacterial endocarditis after dental work. Blood cultures grow alpha-hemolytic, optochin-resistant cocci. Which organism is most likely?', '["Streptococcus pneumoniae", "Viridans streptococci", "Enterococcus faecalis", "Staphylococcus aureus", "Moraxella catarrhalis"]', 1, 'Viridans streptococci are alpha-hemolytic, optochin resistant, and cause subacute endocarditis.', 22),
    (v_topic_id, 'A 70-year-old man develops fever after colon instrumentation. Blood cultures grow gamma-hemolytic cocci that grow in bile and 6.5% NaCl. Which organism is most likely?', '["Streptococcus gallolyticus", "Enterococcus faecalis", "Viridans streptococcus", "Streptococcus pneumoniae", "Staphylococcus epidermidis"]', 1, 'Enterococcus grows in bile and 6.5% NaCl and can cause UTI, endocarditis, and post-GI/GU procedure infections.', 23),
    (v_topic_id, 'An unvaccinated child develops epiglottitis with drooling and respiratory distress. Which virulence factor is most important for this organism?', '["M protein", "PRP capsule", "Protein A", "Urease", "Cord factor"]', 1, 'Haemophilus influenzae type b has a polyribitol phosphate capsule.', 24),
    (v_topic_id, 'A child has conjunctivitis and otitis media. The organism requires factors V and X for growth on chocolate agar. Which organism is most likely?', '["Bordetella pertussis", "Haemophilus influenzae", "Moraxella catarrhalis", "Legionella pneumophila", "Brucella melitensis"]', 1, 'H. influenzae requires factor V (NAD+) and factor X (hemin).', 25),
    (v_topic_id, 'A 4-month-old infant has paroxysmal coughing followed by inspiratory whoop and posttussive vomiting. Lymphocytosis is present. The toxin acts by:', '["Stimulating Gs directly", "ADP-ribosylating Gi, increasing cAMP", "Inactivating EF-2", "Cleaving SNARE proteins", "Blocking guanylate cyclase"]', 1, 'Bordetella pertussis toxin ADP-ribosylates Gi, increasing cAMP.', 26),
    (v_topic_id, 'A hotel guest develops pneumonia, diarrhea, confusion, and hyponatremia. The organism grows on buffered charcoal yeast extract agar. Which organism is most likely?', '["Mycoplasma pneumoniae", "Legionella pneumophila", "Klebsiella pneumoniae", "Chlamydia trachomatis", "Coxiella burnetii"]', 1, 'Legionella causes atypical pneumonia with GI and CNS symptoms and grows on BCYE agar.', 27),
    (v_topic_id, 'A young adult develops atypical pneumonia. Chest X-ray appears worse than physical findings. The organism lacks a cell wall. Which organism is most likely?', '["Chlamydia trachomatis", "Legionella pneumophila", "Mycoplasma pneumoniae", "Coxiella burnetii", "Bordetella pertussis"]', 2, 'Mycoplasma causes walking pneumonia and lacks a cell wall, so beta-lactams are ineffective.', 28),
    (v_topic_id, 'A sexually active man develops urethritis. Gram stain shows no organisms. The pathogen exists in elementary and reticulate body forms. Which organism is most likely?', '["Neisseria gonorrhoeae", "Chlamydia trachomatis", "Treponema pallidum", "Ureaplasma urealyticum", "Mycoplasma genitalium"]', 1, 'Chlamydia is an obligate intracellular organism with elementary bodies and reticulate bodies.', 29),
    (v_topic_id, 'A newborn develops conjunctivitis 1 week after birth. The mother had an untreated STI. The most likely pathogen is:', '["Neisseria gonorrhoeae", "Chlamydia trachomatis", "HSV-2", "Treponema pallidum", "Candida albicans"]', 1, 'Neonatal chlamydial conjunctivitis usually occurs 5–14 days after birth. Gonococcal conjunctivitis occurs earlier and is more severe.', 30),
    (v_topic_id, 'A patient presents with purulent urethritis. Gram stain shows intracellular gram-negative diplococci. Which organism is most likely?', '["Moraxella catarrhalis", "Neisseria gonorrhoeae", "Neisseria meningitidis", "Acinetobacter baumannii", "Haemophilus ducreyi"]', 1, 'Gonorrhea is classically identified by intracellular gram-negative diplococci in neutrophils.', 31),
    (v_topic_id, 'A patient has a painless chancre. Weeks later, diffuse rash involving palms and soles develops. Which diagnostic test is most appropriate to directly visualize the causative organism from the lesion?', '["India ink stain", "Gram stain", "Dark-field microscopy", "Silver methenamine stain", "Acid-fast stain"]', 2, 'Treponema pallidum is a spirochete and can be seen via dark-field microscopy.', 32),
    (v_topic_id, 'A woman has painful genital vesicles with recurrent outbreaks. The virus becomes latent in:', '["Anterior horn cells", "Dorsal root ganglia", "Hepatocytes", "B lymphocytes", "Macrophages"]', 1, 'HSV-2 becomes latent in sensory ganglia, including dorsal root ganglia.', 33),
    (v_topic_id, 'An HIV-positive patient has white plaques on the lateral tongue that do not scrape off. This is most strongly associated with which virus?', '["HSV-1", "EBV", "CMV", "HPV-16", "HHV-8"]', 1, 'Oral hairy leukoplakia is associated with Epstein-Barr virus.', 34),
    (v_topic_id, 'A teenager develops fever, sore throat, and posterior cervical lymphadenopathy. Heterophile antibodies are positive. Which virus is most likely?', '["CMV", "EBV", "Adenovirus", "HIV", "RSV"]', 1, 'Classic infectious mononucleosis with heterophile-positive test is due to EBV.', 35),
    (v_topic_id, 'A transplant recipient develops fever and painful swallowing. Biopsy shows enlarged cells with intranuclear and intracytoplasmic inclusions (“owl eyes”). Which organism is most likely?', '["HSV-1", "EBV", "CMV", "VZV", "HHV-6"]', 2, 'CMV causes esophagitis, retinitis, and colitis in immunocompromised patients. “Owl eye” inclusions are classic.', 36),
    (v_topic_id, 'A child develops vesicular lesions in different stages of healing over the trunk and face. Which virus is the cause?', '["HSV-1", "VZV", "Molluscum contagiosum", "HHV-8", "HPV-6"]', 1, 'Varicella-zoster virus causes chickenpox with lesions in multiple stages.', 37),
    (v_topic_id, 'An older adult develops a painful vesicular rash distributed along a thoracic dermatome. Which virus is responsible?', '["HSV-2", "CMV", "VZV", "Coxsackievirus A", "Parvovirus B19"]', 2, 'Reactivation of varicella-zoster virus causes shingles.', 38),
    (v_topic_id, 'A child with parotitis later develops orchitis. Which viral family does the causative organism belong to?', '["Orthomyxovirus", "Paramyxovirus", "Picornavirus", "Calicivirus", "Reovirus"]', 1, 'Mumps is a Paramyxovirus.', 39),
    (v_topic_id, 'A patient with chronic hepatitis has high risk of hepatocellular carcinoma. The virus is partially double-stranded DNA and uses reverse transcriptase. Which virus is most likely?', '["HAV", "HBV", "HCV", "HDV", "HEV"]', 1, 'HBV is a hepadnavirus with partially double-stranded DNA and reverse transcriptase activity.', 40),
    (v_topic_id, 'A patient develops chronic hepatitis after a blood transfusion years ago. Which virus is most likely?', '["HAV", "HBV", "HCV", "HEV", "Adenovirus"]', 2, 'Hepatitis C commonly becomes chronic and historically was associated with blood transfusion exposure.', 41),
    (v_topic_id, 'A patient with chronic HBV suddenly worsens after superinfection with another virus that requires HBsAg for replication. Which virus is this?', '["HAV", "HCV", "HDV", "HEV", "CMV"]', 2, 'Hepatitis D virus is a defective virus that requires HBsAg from HBV.', 42),
    (v_topic_id, 'A pregnant woman in a developing country develops fulminant hepatitis after contaminated water exposure. Which hepatitis virus is most likely?', '["HAV", "HBV", "HCV", "HEV", "HDV"]', 3, 'HEV is fecal-oral and especially severe in pregnancy.', 43),
    (v_topic_id, 'A child develops severe bronchiolitis in winter. Which virus is most likely?', '["Adenovirus", "RSV", "Parainfluenza virus", "Rhinovirus", "Influenza A"]', 1, 'Respiratory syncytial virus is a common cause of bronchiolitis in infants.', 44),
    (v_topic_id, 'A child has barking cough and inspiratory stridor. The causative organism is most likely:', '["RSV", "Influenza B", "Parainfluenza virus", "Adenovirus", "Coronavirus"]', 2, 'Croup is classically caused by parainfluenza virus.', 45),
    (v_topic_id, 'A patient develops abrupt fever, myalgias, headache, and nonproductive cough in winter. The virus undergoes antigenic drift and shift. Which virus is most likely?', '["RSV", "Rhinovirus", "Influenza A", "Parainfluenza", "Adenovirus"]', 2, 'Influenza A undergoes both antigenic drift and antigenic shift due to segmented genome reassortment.', 46),
    (v_topic_id, 'A child develops mild fever followed by a “slapped cheek” rash. Which virus is most likely?', '["Rubella virus", "HHV-6", "Parvovirus B19", "Coxsackie A virus", "Measles virus"]', 2, 'Parvovirus B19 causes erythema infectiosum and can also trigger aplastic crisis.', 47),
    (v_topic_id, 'An immunocompromised patient develops multifocal demyelination in the brain. Reactivation of which virus is most likely responsible?', '["JC virus", "BK virus", "CMV", "EBV", "HHV-8"]', 0, 'JC virus causes progressive multifocal leukoencephalopathy.', 48),
    (v_topic_id, 'A renal transplant patient develops hemorrhagic cystitis due to a polyomavirus. Which virus is most likely?', '["JC virus", "BK virus", "CMV", "EBV", "Adenovirus"]', 1, 'BK virus is associated with renal transplant complications and hemorrhagic cystitis.', 49),
    (v_topic_id, 'A child on a cruise ship develops acute vomiting and watery diarrhea. Several family members are affected. Which virus is most likely?', '["Rotavirus", "Norovirus", "Poliovirus", "Coxsackievirus B", "Adenovirus 8"]', 1, 'Norovirus is a very common cause of highly contagious outbreaks of gastroenteritis in cruise ships, schools, and nursing homes.', 50),
    (v_topic_id, 'A 6-month-old infant develops severe watery diarrhea with vomiting and fever during winter. Stool studies are negative for bacteria. Which viral characteristic best matches the most likely pathogen?', '["Enveloped, negative-sense segmented RNA", "Nonenveloped, double-stranded segmented RNA", "Enveloped, positive-sense RNA", "Nonenveloped, single-stranded DNA", "Enveloped, double-stranded DNA"]', 1, 'Rotavirus is a Reovirus with segmented dsRNA and is a classic cause of infantile gastroenteritis.', 51),
    (v_topic_id, 'A child develops aseptic meningitis followed by myocarditis. Which virus is most likely responsible?', '["Echovirus", "Coxsackievirus B", "Rotavirus", "Rabies virus", "HSV-2"]', 1, 'Coxsackie B is associated with myocarditis, pericarditis, and aseptic meningitis.', 52),
    (v_topic_id, 'A child presents with painful vesicles in the mouth and on the hands and feet. Which organism is the most likely cause?', '["Coxsackievirus A", "VZV", "Parvovirus B19", "Measles virus", "HSV-1"]', 0, 'Hand-foot-and-mouth disease is classically caused by Coxsackievirus A.', 53),
    (v_topic_id, 'An unvaccinated child develops fever, cough, coryza, conjunctivitis, and Koplik spots followed by a maculopapular rash. Which complication is especially associated with this infection?', '["Aplastic crisis", "Subacute sclerosing panencephalitis", "Kaposi sarcoma", "Hemorrhagic cystitis", "Pseudomembranous colitis"]', 1, 'Measles (rubeola) can cause SSPE, a late neurologic complication.', 54),
    (v_topic_id, 'A pregnant woman is exposed to a child with mild fever and a rash. Her newborn later has congenital cataracts, PDA, and sensorineural deafness. Which organism is most likely?', '["Parvovirus B19", "Rubella virus", "CMV", "Toxoplasma gondii", "HSV-2"]', 1, 'Congenital rubella causes cataracts, PDA, and deafness.', 55),
    (v_topic_id, 'A patient with AIDS develops a vascular tumor of the skin composed of spindle cells. Which virus is the cause?', '["EBV", "HHV-6", "HHV-8", "HPV-16", "JC virus"]', 2, 'Kaposi sarcoma is associated with HHV-8.', 56),
    (v_topic_id, 'A child has recurrent warts on the hands. Which virus is most likely responsible?', '["Molluscum contagiosum virus", "HPV", "HSV-1", "EBV", "CMV"]', 1, 'Common cutaneous warts are caused by human papillomavirus.', 57),
    (v_topic_id, 'A sexually active woman has cervical dysplasia. Which HPV types are most strongly associated with malignancy?', '["1 and 2", "6 and 11", "16 and 18", "4 and 7", "31 and 32 only"]', 2, 'HPV 16 and 18 are high-risk oncogenic strains linked to cervical cancer.', 58),
    (v_topic_id, 'A child develops umbilicated pearly papules on the trunk. Which virus is most likely responsible?', '["HPV", "Molluscum contagiosum virus", "VZV", "HSV-1", "Parvovirus B19"]', 1, 'Molluscum contagiosum causes umbilicated papules.', 59),
    (v_topic_id, 'A person develops hydrophobia, agitation, and confusion weeks after a dog bite. Which histologic finding is classically seen?', '["Owl-eye inclusions", "Guarnieri bodies", "Negri bodies", "Cowdry A inclusions", "Psammoma bodies"]', 2, 'Rabies virus causes Negri bodies in neurons.', 60),
    (v_topic_id, 'A patient with HIV has a CD4 count of 40/mm³ and develops multiple ring-enhancing brain lesions. Serology points to a protozoal infection acquired from cat feces. Which organism is most likely?', '["Cryptosporidium parvum", "Toxoplasma gondii", "Giardia lamblia", "Entamoeba histolytica", "Naegleria fowleri"]', 1, 'Toxoplasma causes brain abscesses in AIDS and is linked to cat feces and undercooked meat.', 61),
    (v_topic_id, 'A pregnant woman acquires primary infection with the same organism described above. Which triad is most consistent with congenital infection?', '["Chorioretinitis, hydrocephalus, intracranial calcifications", "Cataracts, deafness, PDA", "Vesicular rash, limb hypoplasia, chorioretinitis", "Microcephaly, periventricular calcifications, deafness", "Flaccid paralysis, myocarditis, pancreatitis"]', 0, 'Congenital toxoplasmosis classically causes this triad.', 62),
    (v_topic_id, 'A camper develops foul-smelling greasy diarrhea, bloating, and weight loss after drinking from a mountain stream. Which organism is most likely?', '["Entamoeba histolytica", "Giardia lamblia", "Cryptosporidium parvum", "Cyclospora cayetanensis", "Trichomonas vaginalis"]', 1, 'Giardia causes malabsorption, greasy stools, and bloating after contaminated water exposure.', 63),
    (v_topic_id, 'The organism causing the illness in the previous question is best identified by which feature?', '["Trophozoites with ingested RBCs", "Flagellated trophozoites with two nuclei", "Acid-fast oocysts", "Crescent-shaped trophozoites in muscle", "Helminth eggs with bipolar plugs"]', 1, 'Giardia trophozoites have a characteristic face-like appearance with two nuclei.', 64),
    (v_topic_id, 'A man from an endemic region develops flask-shaped colonic ulcers and a liver abscess containing “anchovy paste” material. Which organism is most likely?', '["Giardia lamblia", "Entamoeba histolytica", "Balantidium coli", "Ascaris lumbricoides", "Strongyloides stercoralis"]', 1, 'Entamoeba histolytica causes dysentery and liver abscesses.', 65),
    (v_topic_id, 'Microscopy of stool from the patient above would most strongly support the diagnosis if it showed:', '["Acid-fast oocysts", "Cysts with four nuclei", "Trophozoites containing ingested RBCs", "Flagellated trophozoites", "Budding yeasts"]', 2, 'Ingested RBCs are a classic clue for Entamoeba histolytica.', 66),
    (v_topic_id, 'A patient with AIDS develops chronic watery diarrhea. Stool stain shows acid-fast oocysts. Which organism is the most likely cause?', '["Giardia lamblia", "Entamoeba histolytica", "Cryptosporidium parvum", "Toxoplasma gondii", "Trichuris trichiura"]', 2, 'Cryptosporidium causes persistent diarrhea in immunocompromised patients and is identified by acid-fast oocysts.', 67),
    (v_topic_id, 'A swimmer in a warm freshwater lake develops rapidly fatal meningoencephalitis. Which organism is most likely?', '["Acanthamoeba", "Naegleria fowleri", "Toxoplasma gondii", "Balantidium coli", "Trypanosoma cruzi"]', 1, 'Naegleria fowleri causes primary amebic meningoencephalitis after freshwater exposure.', 68),
    (v_topic_id, 'A contact lens wearer develops keratitis due to a free-living amoeba. Which organism is most likely?', '["Naegleria fowleri", "Acanthamoeba", "Entamoeba histolytica", "Giardia lamblia", "Toxoplasma gondii"]', 1, 'Acanthamoeba causes keratitis, especially in contact lens users.', 69),
    (v_topic_id, 'A woman presents with foul-smelling yellow-green vaginal discharge, vulvar irritation, and a “strawberry cervix.” Which organism is most likely?', '["Candida albicans", "Gardnerella vaginalis", "Trichomonas vaginalis", "Chlamydia trachomatis", "Neisseria gonorrhoeae"]', 2, 'Trichomonas causes frothy discharge and strawberry cervix.', 70),
    (v_topic_id, 'The organism in the previous question is best identified as:', '["An intracellular protozoan", "A flagellated protozoan with no cyst form", "An acid-fast coccidian", "A dimorphic fungus", "A spirochete"]', 1, 'Trichomonas vaginalis is a flagellated protozoan and has no cyst form.', 71),
    (v_topic_id, 'A traveler returning from sub-Saharan Africa has cyclical fevers every 48 hours. Blood smear reveals ring forms inside RBCs. Which organism is most likely?', '["Babesia microti", "Plasmodium falciparum", "Trypanosoma brucei", "Leishmania donovani", "Wuchereria bancrofti"]', 1, 'Malaria with intraerythrocytic ring forms suggests Plasmodium; falciparum is the most severe.', 72),
    (v_topic_id, 'A patient with severe malaria develops cerebral symptoms and renal failure. Which feature is most strongly associated with the most dangerous species?', '["Schuffner dots", "Hypnozoites in the liver", "Banana-shaped gametocytes", "Maltese cross formation", "Microfilariae in blood at night"]', 2, 'Plasmodium falciparum classically shows banana-shaped gametocytes.', 73),
    (v_topic_id, 'A patient with malaria is treated but develops recurrent episodes months later due to dormant liver forms. Which species are most associated with this phenomenon?', '["P. falciparum only", "P. malariae only", "P. vivax and P. ovale", "Babesia microti and P. falciparum", "P. knowlesi only"]', 2, 'Hypnozoites causing relapse are seen in P. vivax and P. ovale.', 74),
    (v_topic_id, 'A hiker in the northeastern United States develops fever and hemolytic anemia after a tick bite. Blood smear shows Maltese cross formations. Which organism is most likely?', '["Plasmodium falciparum", "Babesia microti", "Borrelia burgdorferi", "Ehrlichia chaffeensis", "Leishmania braziliensis"]', 1, 'Babesia is transmitted by Ixodes ticks and shows Maltese cross forms in RBCs.', 75),
    (v_topic_id, 'A missionary returning from Africa develops recurrent somnolence and lymphadenopathy after a tsetse fly bite. Which organism is most likely?', '["Trypanosoma cruzi", "Leishmania donovani", "Trypanosoma brucei", "Toxoplasma gondii", "Babesia microti"]', 2, 'African sleeping sickness is caused by Trypanosoma brucei.', 76),
    (v_topic_id, 'A patient from Latin America develops dilated cardiomyopathy and megacolon years after infection by a reduviid bug. Which organism is responsible?', '["Trypanosoma brucei", "Trypanosoma cruzi", "Leishmania donovani", "Giardia lamblia", "Toxoplasma gondii"]', 1, 'Chagas disease causes dilated cardiomyopathy, megacolon, and megaesophagus.', 77),
    (v_topic_id, 'A child from India has prolonged fever, weight loss, and massive splenomegaly. Amastigotes are seen in macrophages. Which organism is most likely?', '["Trypanosoma cruzi", "Leishmania donovani", "Babesia microti", "Toxoplasma gondii", "Wuchereria bancrofti"]', 1, 'Visceral leishmaniasis (kala-azar) causes fever and splenomegaly.', 78),
    (v_topic_id, 'A man who walked barefoot in contaminated soil develops pruritic rash followed by cough and eosinophilia. Eggs later appear in stool. Which organism is most likely?', '["Enterobius vermicularis", "Ascaris lumbricoides", "Necator americanus", "Taenia solium", "Trichinella spiralis"]', 2, 'Hookworms penetrate skin, migrate through lungs, and can cause iron deficiency anemia.', 79),
    (v_topic_id, 'A child presents with perianal itching, especially at night. Which organism is most likely?', '["Ascaris lumbricoides", "Enterobius vermicularis", "Trichuris trichiura", "Strongyloides stercoralis", "Ancylostoma duodenale"]', 1, 'Pinworm causes perianal pruritus, especially at night.', 80),
    (v_topic_id, 'A patient develops intestinal obstruction from a large worm burden. During migration, transient pulmonary symptoms and eosinophilia occurred. Which organism is most likely?', '["Enterobius vermicularis", "Ascaris lumbricoides", "Trichuris trichiura", "Taenia saginata", "Schistosoma mansoni"]', 1, 'Ascaris can cause lung migration symptoms and later intestinal obstruction.', 81),
    (v_topic_id, 'A child from a tropical region has rectal prolapse and dysentery. Stool reveals barrel-shaped eggs with bipolar plugs. Which organism is most likely?', '["Trichuris trichiura", "Enterobius vermicularis", "Ascaris lumbricoides", "Strongyloides stercoralis", "Diphyllobothrium latum"]', 0, 'Whipworm causes rectal prolapse and has barrel-shaped eggs with bipolar plugs.', 82),
    (v_topic_id, 'A patient receiving corticosteroids develops severe disseminated helminth infection due to autoinfection. Which organism is most likely?', '["Ascaris lumbricoides", "Enterobius vermicularis", "Strongyloides stercoralis", "Taenia saginata", "Wuchereria bancrofti"]', 2, 'Strongyloides can cause hyperinfection syndrome, especially in immunosuppressed patients.', 83),
    (v_topic_id, 'A patient develops myalgias, periorbital edema, and eosinophilia after eating undercooked pork. Which organism is most likely?', '["Taenia solium", "Trichinella spiralis", "Ascaris lumbricoides", "Enterobius vermicularis", "Schistosoma haematobium"]', 1, 'Trichinella from undercooked pork causes muscle invasion, myalgias, and eosinophilia.', 84),
    (v_topic_id, 'A man develops seizures, and imaging reveals multiple cystic brain lesions. He acquired the infection from eggs shed in human feces. Which organism is most likely?', '["Taenia saginata", "Diphyllobothrium latum", "Echinococcus granulosus", "Taenia solium", "Trichinella spiralis"]', 3, 'Neurocysticercosis is due to T. solium eggs.', 85),
    (v_topic_id, 'A patient has megaloblastic anemia after eating raw freshwater fish. Which organism is the most likely cause?', '["Taenia solium", "Diphyllobothrium latum", "Ascaris lumbricoides", "Trichinella spiralis", "Fasciola hepatica"]', 1, 'Fish tapeworm causes vitamin B12 deficiency and megaloblastic anemia.', 86),
    (v_topic_id, 'A sheep farmer develops a slowly enlarging cystic liver lesion. Rupture could cause anaphylaxis. Which organism is most likely?', '["Taenia solium", "Echinococcus granulosus", "Schistosoma mansoni", "Fasciola hepatica", "Clonorchis sinensis"]', 1, 'Hydatid cysts are caused by Echinococcus.', 87),
    (v_topic_id, 'A patient develops hematuria and is later diagnosed with squamous cell carcinoma of the bladder. Which parasite is most strongly associated?', '["Schistosoma mansoni", "Schistosoma japonicum", "Schistosoma haematobium", "Enterobius vermicularis", "Ascaris lumbricoides"]', 2, 'S. haematobium affects the urinary tract and is linked to bladder SCC.', 88),
    (v_topic_id, 'A farmer develops portal hypertension and hepatosplenomegaly after freshwater exposure. Stool contains eggs with large lateral spines. Which organism is most likely?', '["Schistosoma haematobium", "Schistosoma mansoni", "Schistosoma japonicum", "Fasciola hepatica", "Clonorchis sinensis"]', 1, 'S. mansoni causes portal hypertension and has large lateral spine eggs.', 89),
    (v_topic_id, 'A woman develops vaginal itching and thick white discharge. Microscopy shows budding yeast and pseudohyphae. Which organism is most likely?', '["Gardnerella vaginalis", "Trichomonas vaginalis", "Candida albicans", "Chlamydia trachomatis", "Neisseria gonorrhoeae"]', 2, 'Candida causes vulvovaginitis with curd-like discharge and pseudohyphae.', 90),
    (v_topic_id, 'A neutropenic patient has hemoptysis and chest CT showing nodules. Histology reveals septate hyphae branching at acute angles. Which organism is most likely?', '["Candida albicans", "Aspergillus fumigatus", "Rhizopus species", "Cryptococcus neoformans", "Histoplasma capsulatum"]', 1, 'Aspergillus shows acute-angle septate hyphae and causes invasive disease in neutropenia.', 91),
    (v_topic_id, 'A patient in diabetic ketoacidosis develops facial pain and black necrotic tissue in the nasal cavity. Biopsy shows broad nonseptate hyphae with right-angle branching. Which organism is most likely?', '["Aspergillus fumigatus", "Candida albicans", "Mucor/Rhizopus", "Histoplasma capsulatum", "Coccidioides immitis"]', 2, 'Mucormycosis is classically seen in DKA.', 92),
    (v_topic_id, 'A patient with AIDS develops meningitis. India ink is positive. Which virulence factor is most important for the causative organism?', '["Mycolic acid", "Polysaccharide capsule", "Actin polymerization", "Endotoxin", "Urease-negative cell wall"]', 1, 'Cryptococcus neoformans has a prominent polysaccharide capsule.', 93),
    (v_topic_id, 'A spelunker from the Ohio River valley develops pulmonary infection. Macrophages contain small oval yeasts. Which organism is most likely?', '["Blastomyces dermatitidis", "Histoplasma capsulatum", "Coccidioides immitis", "Sporothrix schenckii", "Candida albicans"]', 1, 'Histoplasma is found in bird/bat droppings and lives in macrophages.', 94),
    (v_topic_id, 'A hunter from the Mississippi basin has pulmonary symptoms and verrucous skin lesions. Broad-based budding yeast are seen. Which organism is most likely?', '["Histoplasma capsulatum", "Blastomyces dermatitidis", "Coccidioides immitis", "Cryptococcus neoformans", "Sporothrix schenckii"]', 1, 'Blastomyces shows broad-based budding and can affect lungs and skin.', 95),
    (v_topic_id, 'A construction worker in Arizona develops fever, cough, arthralgias, and erythema nodosum after dust exposure. Tissue shows spherules filled with endospores. Which organism is most likely?', '["Histoplasma capsulatum", "Blastomyces dermatitidis", "Coccidioides immitis", "Candida albicans", "Sporothrix schenckii"]', 2, 'Coccidioides is found in the Southwestern US and forms spherules.', 96),
    (v_topic_id, 'A gardener develops nodules along lymphatic channels after a thorn prick. Which organism is most likely?', '["Sporothrix schenckii", "Histoplasma capsulatum", "Blastomyces dermatitidis", "Cryptococcus neoformans", "Candida albicans"]', 0, 'Sporothrix causes sporotrichoid spread after rose thorn injury.', 97),
    (v_topic_id, 'Which of the following organisms is intrinsically resistant to beta-lactam antibiotics because it lacks a peptidoglycan cell wall?', '["Chlamydia trachomatis", "Mycoplasma pneumoniae", "Neisseria gonorrhoeae", "Legionella pneumophila", "Rickettsia rickettsii"]', 1, 'Mycoplasma lacks a true cell wall, making beta-lactams ineffective.', 98),
    (v_topic_id, 'A bacterium is classified as acid-fast because of which cell wall component?', '["Lipopolysaccharide", "Teichoic acid", "Mycolic acid", "Peptidoglycan cross-bridges", "Dextran"]', 2, 'Mycobacteria are acid-fast due to mycolic acids in the cell wall.', 99),
    (v_topic_id, 'Which sterilization method is most appropriate for heat-sensitive medical equipment and kills all organisms including spores?', '["Boiling water", "Pasteurization", "Ethylene oxide gas", "Alcohol rub", "UV light"]', 2, 'Ethylene oxide is used to sterilize heat-sensitive equipment and is sporicidal.', 100),
    (v_topic_id, 'A man with weight loss, chronic cough, night sweats, and hemoptysis has upper lobe cavitary lesions on chest imaging. Which virulence factor is most associated with the causative organism’s pathogenicity?', '["Endotoxin", "Cord factor", "M protein", "IgA protease", "Capsule PRP"]', 1, 'Mycobacterium tuberculosis is associated with cord factor (trehalose dimycolate), which promotes granuloma formation and TNF-α release.', 101),
    (v_topic_id, 'A patient is screened for latent tuberculosis infection with purified protein derivative (PPD). A positive result is primarily mediated by which immune mechanism?', '["Antibody-mediated cytotoxicity", "Type I hypersensitivity", "Type II hypersensitivity", "Type III hypersensitivity", "Type IV hypersensitivity"]', 4, 'The PPD test measures a delayed-type (Type IV) hypersensitivity reaction mediated by T cells.', 102),
    (v_topic_id, 'A patient with HIV develops disseminated infection by Mycobacterium avium complex. Which stain is most useful to visualize the organism?', '["India ink", "Acid-fast stain", "Silver stain", "Gram stain", "Wright stain"]', 1, 'Mycobacteria are visualized using acid-fast staining because of their mycolic acid-rich cell walls.', 103),
    (v_topic_id, 'A patient from the southern United States develops chronic skin nodules and peripheral neuropathy. Biopsy shows acid-fast bacilli, and the organism cannot be cultured on standard media. Which organism is most likely?', '["Mycobacterium tuberculosis", "Mycobacterium kansasii", "Mycobacterium leprae", "Nocardia asteroides", "Actinomyces israelii"]', 2, 'M. leprae causes leprosy and prefers cooler body areas. It cannot be cultured in vitro and affects skin and peripheral nerves.', 104),
    (v_topic_id, 'Tuberculoid leprosy is best characterized by which of the following?', '["Weak cell-mediated immunity and numerous organisms", "Strong cell-mediated immunity and few organisms", "No granuloma formation", "Diffuse foamy macrophages with widespread bacilli", "High bacterial load and leonine facies"]', 1, 'Tuberculoid leprosy features strong Th1 response, granulomas, and low organism burden.', 105),
    (v_topic_id, 'A farmer develops pneumonia after exposure to livestock birthing products. The organism is an obligate intracellular pathogen associated with Q fever. Which organism is most likely?', '["Rickettsia rickettsii", "Coxiella burnetii", "Ehrlichia chaffeensis", "Chlamydia psittaci", "Bartonella henselae"]', 1, 'Q fever is caused by Coxiella burnetii, often acquired from livestock aerosols.', 106),
    (v_topic_id, 'A hiker in North Carolina develops fever, headache, and rash that begins on wrists and ankles then spreads centrally. Which organism is most likely?', '["Rickettsia prowazekii", "Rickettsia rickettsii", "Borrelia recurrentis", "Ehrlichia chaffeensis", "Babesia microti"]', 1, 'Rocky Mountain spotted fever causes rash starting on wrists/ankles and involves palms/soles.', 107),
    (v_topic_id, 'The organism in the previous question primarily infects which cells?', '["Hepatocytes", "B lymphocytes", "Vascular endothelial cells", "Enterocytes", "Motor neurons"]', 2, 'Rickettsia rickettsii infects endothelial cells, leading to vasculitis.', 108),
    (v_topic_id, 'A patient from a homeless shelter develops recurrent louse-borne typhus. Which organism is most likely?', '["Rickettsia rickettsii", "Coxiella burnetii", "Rickettsia prowazekii", "Ehrlichia chaffeensis", "Bartonella quintana"]', 2, 'R. prowazekii causes epidemic typhus and is spread by lice.', 109),
    (v_topic_id, 'A patient presents with fever, headache, leukopenia, and thrombocytopenia after a tick bite. Peripheral smear shows morulae in monocytes. Which organism is most likely?', '["Anaplasma phagocytophilum", "Ehrlichia chaffeensis", "Babesia microti", "Borrelia burgdorferi", "Coxiella burnetii"]', 1, 'Ehrlichia infects monocytes and forms morulae.', 110),
    (v_topic_id, 'A similar patient has morulae in neutrophils instead. Which organism is most likely?', '["Ehrlichia chaffeensis", "Anaplasma phagocytophilum", "Rickettsia rickettsii", "Coxiella burnetii", "Bartonella henselae"]', 1, 'Anaplasma infects neutrophils, whereas Ehrlichia infects monocytes.', 111),
    (v_topic_id, 'A pet store worker develops atypical pneumonia after exposure to parrots. Which organism is most likely?', '["Chlamydia trachomatis", "Chlamydia psittaci", "Mycoplasma pneumoniae", "Coxiella burnetii", "Legionella pneumophila"]', 1, 'Psittacosis is caused by Chlamydia psittaci and is associated with birds.', 112),
    (v_topic_id, 'A newborn develops afebrile pneumonia with staccato cough and eosinophilia. Which organism is most likely?', '["RSV", "Chlamydia trachomatis", "Bordetella pertussis", "CMV", "Streptococcus agalactiae"]', 1, 'Neonatal chlamydial pneumonia presents with staccato cough and often eosinophilia.', 113),
    (v_topic_id, 'A sexually active woman has bacterial vaginosis with clue cells on microscopy. Which organism is most likely?', '["Candida albicans", "Trichomonas vaginalis", "Gardnerella vaginalis", "Neisseria gonorrhoeae", "Chlamydia trachomatis"]', 2, 'Gardnerella causes bacterial vaginosis with clue cells, thin discharge, and fishy odor.', 114),
    (v_topic_id, 'A woman has normal vaginal flora dominated by an organism that helps maintain low vaginal pH. Which organism is most responsible?', '["Escherichia coli", "Lactobacillus", "Gardnerella", "Bacteroides fragilis", "Candida albicans"]', 1, 'Lactobacilli maintain acidic vaginal pH by producing lactic acid.', 115),
    (v_topic_id, 'A patient develops infective endocarditis, and blood cultures grow Streptococcus gallolyticus. This finding should prompt evaluation for:', '["Colon carcinoma", "Bladder carcinoma", "Lung abscess", "HIV infection", "Splenic rupture"]', 0, 'Streptococcus gallolyticus bacteremia/endocarditis is associated with colon neoplasia.', 116),
    (v_topic_id, 'A patient develops pseudomembranous pharyngitis. Laboratory confirmation of toxigenic strain uses which test?', '["Quellung reaction", "Elek test", "CAMP test", "Urease test", "Coagulase test"]', 1, 'The Elek test detects diphtheria toxin production.', 117),
    (v_topic_id, 'Which of the following organisms is most likely to produce beta-lactamase and cause otitis media in children and sinusitis in adults?', '["Moraxella catarrhalis", "Streptococcus pyogenes", "Listeria monocytogenes", "Corynebacterium diphtheriae", "Bacillus anthracis"]', 0, 'Moraxella is a common cause of otitis/sinusitis and often produces beta-lactamase.', 118),
    (v_topic_id, 'A microbiology lab identifies a gram-negative rod that is oxidase positive and produces blue-green pigment. Which organism is most likely?', '["Klebsiella pneumoniae", "Escherichia coli", "Pseudomonas aeruginosa", "Proteus mirabilis", "Salmonella enterica"]', 2, 'Pseudomonas is oxidase positive and produces pyocyanin/pyoverdine pigments.', 119),
    (v_topic_id, 'A burn patient develops sepsis due to the organism above. Which virulence factor inhibits elongation factor-2, similar to diphtheria toxin?', '["Exotoxin A", "Endotoxin", "Elastase", "Lecithinase", "Coagulase"]', 0, 'Pseudomonas exotoxin A inhibits EF-2 by ADP-ribosylation.', 120),
    (v_topic_id, 'A cystic fibrosis patient has chronic lung colonization with mucoid bacteria. Which organism is most likely?', '["Streptococcus pneumoniae", "Pseudomonas aeruginosa", "Moraxella catarrhalis", "Mycoplasma pneumoniae", "Corynebacterium diphtheriae"]', 1, 'Pseudomonas commonly colonizes CF lungs.', 121),
    (v_topic_id, 'A child has osteomyelitis after stepping on a nail through a sneaker. Which organism is classically implicated?', '["Staphylococcus epidermidis", "Pseudomonas aeruginosa", "Streptococcus pyogenes", "Enterococcus faecalis", "Bacteroides fragilis"]', 1, 'Pseudomonas osteomyelitis is classic after puncture wounds through sneakers.', 122),
    (v_topic_id, 'An anaerobic gram-negative rod from the colon is isolated from an intra-abdominal abscess. Which organism is most likely?', '["Fusobacterium nucleatum", "Bacteroides fragilis", "Clostridium perfringens", "Actinomyces israelii", "Nocardia asteroides"]', 1, 'B. fragilis is a major anaerobe in intra-abdominal abscesses.', 123),
    (v_topic_id, 'A woman with long-term IUD use develops pelvic infection with sulfur granules in draining tracts. Which organism is most likely?', '["Nocardia asteroides", "Actinomyces israelii", "Listeria monocytogenes", "Bacillus anthracis", "Mycobacterium leprae"]', 1, 'Actinomyces causes abscesses with sulfur granules and is associated with IUDs.', 124),
    (v_topic_id, 'Which feature best distinguishes Nocardia from Actinomyces?', '["Gram-negative staining", "Acid-fastness and aerobic growth", "Endospore formation", "Intracellular growth in macrophages", "Presence of polysaccharide capsule"]', 1, 'Nocardia is weakly acid-fast and aerobic; Actinomyces is not acid-fast and is anaerobic.', 125),
    (v_topic_id, 'An immunocompromised patient develops pneumonia with branching filamentous weakly acid-fast organisms. Which organism is most likely?', '["Actinomyces israelii", "Nocardia asteroides", "Mycobacterium tuberculosis", "Listeria monocytogenes", "Clostridium perfringens"]', 1, 'Nocardia causes pulmonary and CNS disease in immunocompromised patients.', 126),
    (v_topic_id, 'A microbiology student asks which property allows Neisseria gonorrhoeae to repeatedly reinfect the same individual. The best answer is:', '["Endospore formation", "Antigenic variation of pili", "Capsule switching", "Latency in neurons", "Integration into host genome"]', 1, 'N. gonorrhoeae frequently changes pili antigens, allowing immune evasion.', 127),
    (v_topic_id, 'Which organism is most likely to cause septic arthritis in a sexually active young adult with migratory polyarthralgia and pustular rash?', '["Staphylococcus aureus", "Neisseria gonorrhoeae", "Chlamydia trachomatis", "Borrelia burgdorferi", "Treponema pallidum"]', 1, 'Disseminated gonococcal infection can cause tenosynovitis, dermatitis, and septic arthritis.', 128),
    (v_topic_id, 'A patient with Lyme disease develops facial nerve palsy and heart block. Which vector transmitted the disease?', '["Lone star tick", "Dog tick", "Deer tick (Ixodes)", "Tsetse fly", "Sandfly"]', 2, 'Borrelia burgdorferi is transmitted by the Ixodes tick.', 129),
    (v_topic_id, 'The rash of early Lyme disease is best described as:', '["Vesicular dermatomal rash", "Bullous necrotic lesion", "Target-like expanding erythematous lesion", "Petechial rash beginning on wrists and ankles", "Diffuse desquamating rash"]', 2, 'Erythema migrans is the classic rash of early Lyme disease.', 130),
    (v_topic_id, 'A homeless man with poor hygiene develops relapsing fever due to a spirochete transmitted by body lice. Which organism is most likely?', '["Treponema pallidum", "Borrelia recurrentis", "Borrelia burgdorferi", "Leptospira interrogans", "Campylobacter jejuni"]', 1, 'Relapsing fever can be caused by Borrelia recurrentis via lice.', 131),
    (v_topic_id, 'A sewer worker develops fever, conjunctival suffusion, jaundice, and renal dysfunction after exposure to contaminated water. Which organism is most likely?', '["Leptospira interrogans", "Borrelia burgdorferi", "Treponema pallidum", "Rickettsia rickettsii", "Coxiella burnetii"]', 0, 'Leptospirosis is associated with contaminated water and animal urine.', 132),
    (v_topic_id, 'Which virus is most strongly associated with aplastic crisis in a child with sickle cell disease?', '["EBV", "Parvovirus B19", "CMV", "Rubella", "VZV"]', 1, 'Parvovirus B19 infects erythroid precursors and can cause aplastic crisis.', 133),
    (v_topic_id, 'Which virus is the only single-stranded DNA virus classically tested on USMLE microbiology?', '["Adenovirus", "HBV", "Parvovirus B19", "Papillomavirus", "Polyomavirus"]', 2, 'High-yield exception: Parvovirus B19 is a single-stranded DNA virus.', 134),
    (v_topic_id, 'A child has roseola infantum with high fever followed by rash after defervescence. Which virus is most likely?', '["HHV-6", "HHV-8", "EBV", "CMV", "HSV-2"]', 0, 'Roseola is caused by HHV-6.', 135),
    (v_topic_id, 'Which virus is most strongly associated with Burkitt lymphoma?', '["CMV", "EBV", "HHV-8", "JC virus", "HBV"]', 1, 'EBV is associated with Burkitt lymphoma, nasopharyngeal carcinoma, and others.', 136),
    (v_topic_id, 'A child has acute hemorrhagic cystitis caused by a DNA virus. Which organism is most likely?', '["BK virus", "Adenovirus", "JC virus", "HSV-1", "Parvovirus B19"]', 1, 'Adenovirus can cause respiratory disease, conjunctivitis, and hemorrhagic cystitis.', 137),
    (v_topic_id, 'A virology question asks which virus is nonenveloped and therefore relatively resistant to drying, detergents, and acid. Which of the following fits best?', '["HIV", "Influenza A", "HSV-1", "Adenovirus", "CMV"]', 3, 'Nonenveloped viruses are generally more environmentally stable.', 138),
    (v_topic_id, 'Which of the following viruses carries its own RNA-dependent RNA polymerase inside the virion because host cells cannot transcribe its genome directly?', '["Picornavirus", "Flavivirus", "Reovirus", "Adenovirus", "Parvovirus"]', 2, 'Double-stranded RNA viruses like Reovirus require a viral RNA polymerase.', 139),
    (v_topic_id, 'Which viruses must carry reverse transcriptase?', '["Orthomyxoviruses only", "Retroviruses and Hepadnaviruses", "Picornaviruses and Caliciviruses", "Reoviruses only", "Paramyxoviruses only"]', 1, 'Retroviruses and HBV (a hepadnavirus) require reverse transcriptase.', 140),
    (v_topic_id, 'Which of the following best defines sterilization?', '["Removal of vegetative bacteria only", "Removal of all microorganisms except spores", "Elimination of all forms of microbial life including spores", "Reduction of microbial load to safe public health levels", "Use of soap and water to physically remove organisms"]', 2, 'Sterilization destroys all organisms including spores.', 141),
    (v_topic_id, 'Which of the following methods disinfects water supplies primarily by oxidizing microbial cellular components?', '["Ethylene oxide", "Autoclaving", "Chlorination", "Formaldehyde gas", "Filtration"]', 2, 'Chlorine is widely used in water disinfection through oxidation.', 142),
    (v_topic_id, 'Which method is best for sterilizing heat-stable surgical instruments?', '["Boiling water", "UV radiation", "Autoclaving", "Alcohol swab", "Refrigeration"]', 2, 'Autoclaving uses steam under pressure and sterilizes even spores.', 143),
    (v_topic_id, 'Pasteurization is best described as:', '["Complete sterilization of surgical tools", "Heating to reduce microbial burden in liquids without full sterilization", "Use of dry heat to destroy spores", "Chemical sterilization of plastics", "Filtration of protein-containing fluids"]', 1, 'Pasteurization lowers pathogen burden but does not sterilize.', 144),
    (v_topic_id, 'A hospital uses alcohol-based hand rub. Which of the following is true regarding alcohols?', '["They kill spores reliably", "They are useful for sterilizing surgical packs", "They denature proteins and disrupt membranes", "They are ineffective against enveloped viruses", "They work by alkylating nucleic acids"]', 2, 'Alcohols are good antiseptics but do not kill spores reliably.', 145),
    (v_topic_id, 'Which of the following agents is most effective against bacterial spores?', '["Quaternary ammonium compounds", "Alcohol", "Chlorhexidine", "Autoclave steam", "Soap"]', 3, 'Spores are highly resistant; autoclaving is reliably sporicidal.', 146),
    (v_topic_id, 'Prion diseases are caused by:', '["Defective RNA viruses", "Misfolded proteins lacking nucleic acid", "Intracellular bacteria without cell wall", "Slow-growing fungi", "Protozoa with altered antigenic variation"]', 1, 'Prions are infectious misfolded proteins with no nucleic acid.', 147),
    (v_topic_id, 'A patient develops rapidly progressive dementia, ataxia, and myoclonus. EEG shows periodic sharp waves. Which disease is most likely?', '["Progressive multifocal leukoencephalopathy", "Creutzfeldt-Jakob disease", "Subacute sclerosing panencephalitis", "Rabies", "Neurosyphilis"]', 1, 'CJD is a classic human prion disease.', 148),
    (v_topic_id, 'Which of the following best explains why patients receiving broad-spectrum antibiotics are more prone to Clostridioides difficile infection?', '["Antibiotics induce toxin genes directly", "Loss of normal flora colonization resistance", "Increased gastric acid secretion", "Enhanced T-cell suppression", "Development of viral superinfection"]', 1, 'Normal microbiota provide colonization resistance. Antibiotics disrupt this protection.', 149),
    (v_topic_id, 'A student asks which organism is part of normal human flora but becomes an opportunistic pathogen causing thrush and esophagitis when host defenses are weakened. Which organism is the best answer?', '["Cryptococcus neoformans", "Candida albicans", "Histoplasma capsulatum", "Aspergillus fumigatus", "Coccidioides immitis"]', 1, 'Candida albicans is normal mucocutaneous flora and becomes opportunistic in immunocompromised states.', 150)
