-- ============================================================
-- USMLE Step 1 Microbiology MCQ Migration (150 Questions)
-- Topic: Microbiology (USMLE Step 1)
-- ============================================================

DO $$
DECLARE
    v_topic_id UUID;
BEGIN
    -- 1. Get or Create Topic ID for Microbiology (USMLE Step 1)
    SELECT id INTO v_topic_id FROM public.topics WHERE title = 'Microbiology' AND usmle_step = 1;

    IF v_topic_id IS NULL THEN
        VALUES ('Microbiology', 'microbiology', 1, 0)
        RETURNING id INTO v_topic_id;
    END IF;

    -- 2. Insert 150 MCQs
    ON CONFLICT DO NOTHING;
END $$;
